CSS = open(os.path.join(os.path.dirname(OUT), 'POT_guia.html')).read().split('<style>')[1].split('</style>')[0]
CSS += 'td.sec{white-space:normal;font-family:var(--sans);font-weight:500;font-size:13px;width:22%}td:nth-child(2){width:48%}.src{font-size:12px;color:var(--muted);white-space:nowrap}.part{color:var(--ask);border:1px solid var(--ask)}.miss{color:#b42318;border:1px solid #b42318}.note{font-size:13px;color:var(--muted)}'
TAG = {C: '<span class="tag ok">coberto</span>', P: '<span class="tag part">parcial</span>', F: '<span class="tag miss">falta</span>'}
e = html.escape
for acr, d in G.items():
    rows = ''.join(f'<tr><td>{i}</td><td>{e(r)}</td><td class="src">{e(s)}</td><td class="sec">{e(w)}</td><td>{TAG[st]}</td></tr>' for i, (r, s, w, st) in enumerate(d['req'], 1))
    h = f'''<!doctype html><html lang="pt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{acr} · guia</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@500;600&display=swap"><style>{CSS}</style></head><body><div class="wrap">
<div class="card"><h1><span class="mono">{acr}</span> · {e(d['name'])}</h1><p class="lead">{e(d['lead'])}</p><p class="note">Base: texto da tese (Caps. 4 e 5, Tabela 4.3). Itens marcados "inferido" não estão escritos na tese. "Onde está" se refere à versão atual, {e(d['ver'])}.</p></div>
<div class="card"><h2>Que problema ele resolve</h2><p>{e(d['prob'])}</p></div>
<div class="card"><h2>Como a informação passa por ele</h2><div class="flow"><div class="box"><b>Entra</b>{e(d['inn'])}</div><div class="arrow" aria-hidden="true">→</div><div class="box"><b>No {acr}</b>{e(d['mid'])}</div><div class="arrow" aria-hidden="true">→</div><div class="box"><b>Sai</b>{e(d['out'])}</div></div></div>
<div class="card"><h2>O que ele tem que cobrir</h2><div class="tbl"><table><tr><th>#</th><th>O {acr} precisa…</th><th>Fonte</th><th>Onde está</th><th>Situação</th></tr>{rows}</table></div></div>
<div class="card"><h2>O que ele não faz</h2><ul>{''.join(f'<li>{e(x)}</li>' for x in d['nao'])}</ul></div>
<div class="card"><h2>Para você decidir</h2><ol>{''.join(f'<li>{e(x)}</li>' for x in d['q'])}</ol></div>
</div></body></html>'''
    open(os.path.join(os.path.dirname(OUT), f'{acr}_guia.html'), 'w').write(h)
print('ok', len(G))
